contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test driving calls and ending with one assert
    function runTest(address sender, uint amt) public payable {
        // preconditions: sender is this contract for direct calls via address(this)
        // but P's Deposit credits msg.sender, so we must call Deposit from this contract
        // ensure the input amount is available as ether in this contract
        require(msg.sender != address(0));
        require(address(this).balance >= amt, "need funds");
        // record prior balance for this contract's address on target contract
        uint prior = c.balances(address(this));

        // perform Deposit on target contract, sending amt wei
        c.Deposit{value: amt}();

        // read after state
        uint after = c.balances(address(this));

        // property: the caller's balance increased exactly by amt
        assert(after - prior == amt);
    }

    // allow funding this test contract so it can forward ETH
    receive() external payable {}
}

