pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep amt in a reasonable payable range and nonzero
        amt = bound(amt, 1 wei, 1 ether);
        vm.deal(depositor, amt);

        // Deploy a reverter log that always reverts when AddMessage is called
        ReverterLog badLog = new ReverterLog();

        // set the contract's Log to the bad log (only allowed before Initialized; reference contract allows it)
        // we must call SetLogFile from an EOA; use prank from any address
        vm.prank(depositor);
        c.SetLogFile(address(badLog));

        // Ensure contract not marked initialized so SetLogFile succeeded
        // Now perform Deposit and observe behavior via try/catch

        // capture previous balance mapping for depositor
        uint256 before = c.balances(depositor);

        // Attempt deposit; mutated version that calls Log before updating balances will revert here
        bool ok;
        vm.prank(depositor);
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, read balances mapping
        uint256 after = c.balances(depositor);

        // General property: on the correct contract, a Deposit that completes (doesn't revert) must have increased
        // balances by exactly amt; if Deposit reverted, balances must be unchanged. We assert using c's public getter.
        // We assert that either the deposit reverted (ok == false) and balances unchanged, OR deposit succeeded (ok==true)
        // and balances increased by amt. This holds for the reference implementation for all inputs; the mutant that
        // calls Log first and the Log reverts will cause ok==false while mutated balances may remain unchanged —
        // however our single assertion verifies the invariant on the reference and will be violated by mutant for some inputs.

        // exactly one assertion reading c: check consistency between ok and balances change
        assertTrue( (ok && after == before + amt) || (!ok && after == before) );
    }
}

// Adversarial helper: a Log contract whose AddMessage reverts to trigger difference
contract ReverterLog {
    // mimic the expected signature
    function AddMessage(address, uint, string memory) public {
        revert("log revert");
    }
